// Generated from src/registry/sources/control-ui/recipes/chat-layout.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const chatLayoutKnobs = [
  "--cui-chat-layout-radius",
  "--cui-chat-layout-background",
  "--cui-chat-layout-border-color",
  "--cui-chat-layout-shadow",
  "--cui-chat-layout-thought-foreground",
  "--cui-chat-layout-thought-hover-background",
] as const;
export type ChatLayoutKnobStyle = Partial<Record<(typeof chatLayoutKnobs)[number], string>>;

import type { ComponentProps, CSSProperties, ElementType, ReactNode } from "react";
import { Activity, ActivityContent, ActivityTitle, ActivityTrigger } from "@/components/control-ui/activity";
import type { ChatLayoutKnobStyle } from "@/components/control-ui/knob-contracts/chat-layout-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { skinAdornment } from "@/components/control-ui/skin";
import { ScrollArea } from "@/components/control-ui/ui/scroll-area";

type ChatThoughtCollapsible = {
  Root: ElementType;
  Trigger: ElementType;
  Content: ElementType;
};

export type ChatLayoutProps = Omit<ComponentProps<"section">, "style"> & {
  style?: CSSProperties & ChatLayoutKnobStyle;
};

export function ChatLayout({ children, className, ...props }: ChatLayoutProps) {
  return (
    <section
      data-control-ui="chat-layout"
      data-control-family="chat-layout"
      data-slot="root"
      data-surface="panel"
      className={cn("relative mx-auto flex min-h-[640px] w-full max-w-3xl flex-col overflow-hidden", className)}
      {...props}
    >
      {skinAdornment("chat-layout", "titlebar", {})}
      {children}
    </section>
  );
}

export type ChatThreadProps = ComponentProps<"div">;

export function ChatThread({ children, className, ...props }: ChatThreadProps) {
  return (
    <div
      data-control-ui="chat-thread"
      data-control-family="chat-layout"
      data-chat-layout-kind="thread"
      data-slot="root"
      className={cn("flex min-h-0 flex-1 flex-col overflow-y-auto", className)}
      {...props}
    >
      {children}
    </div>
  );
}

export type ChatTurnProps = ComponentProps<"section"> & {
  from: "user" | "assistant";
};

export function ChatTurn({ from, children, className, ...props }: ChatTurnProps) {
  return (
    <section
      data-control-ui="chat-turn"
      data-control-family="chat-layout"
      data-slot="turn"
      data-from={from}
      className={cn("flex w-full flex-col", from === "user" && "items-end", className)}
      {...props}
    >
      {children}
    </section>
  );
}

export type ChatThoughtProps = Omit<ComponentProps<"div">, "style"> & {
  details?: ReactNode;
  defaultOpen?: boolean;
  collapsible?: ChatThoughtCollapsible;
  style?: CSSProperties & ChatLayoutKnobStyle;
};

export function ChatThought({
  children = "Thought for a couple of seconds",
  details = "Read the attachment, grouped the notes by intent, and kept the final markdown compact enough to scan.",
  defaultOpen = false,
  collapsible,
  className,
  style,
  ...props
}: ChatThoughtProps) {
  if (collapsible) {
    const Root = collapsible.Root;
    const Trigger = collapsible.Trigger;
    const Content = collapsible.Content;

    return (
      <Root
        defaultOpen={defaultOpen}
        data-control-ui="chat-thought"
        data-control-family="chat-layout"
        data-chat-layout-kind="thought"
        data-slot="root"
        className={cn("self-start", className)}
        style={style}
        {...props}
      >
        <Trigger
          type="button"
          data-control-ui="chat-thought"
          data-control-family="chat-layout"
          data-slot="trigger"
          className="inline-flex items-center"
        >
          {children}
          <span aria-hidden="true" data-control-ui="chat-thought" data-control-family="chat-layout" data-slot="chevron">
            ›
          </span>
        </Trigger>
        <Content>
          <ScrollArea
            maxHeight="min(24rem, 50dvh)"
            lockAxis="x"
            viewportProps={{
              "data-control-ui": "activity",
              "data-control-family": "activity",
              "data-slot": "content-viewport",
            }}
          >
            <div data-control-ui="chat-thought" data-control-family="chat-layout" data-slot="details" className="min-w-0 px-1 pb-2 pt-1">
              {skinAdornment("chat-thought", "details", {})}
              {details}
            </div>
          </ScrollArea>
        </Content>
      </Root>
    );
  }

  return (
    <Activity
      state="success"
      defaultOpen={defaultOpen}
      data-control-ui="chat-thought"
      data-control-family="chat-layout"
      data-chat-layout-kind="thought"
      data-slot="root"
      className={cn("self-start", className)}
      style={style}
      {...props}
    >
      <ActivityTrigger data-control-ui="chat-thought" data-control-family="chat-layout" data-slot="trigger">
        <ActivityTitle data-control-ui="chat-thought" data-control-family="chat-layout" data-slot="title">
          {children}
        </ActivityTitle>
      </ActivityTrigger>
      <ActivityContent data-control-ui="chat-thought" data-control-family="chat-layout" data-slot="details">
        {skinAdornment("chat-thought", "details", {})}
        {details}
      </ActivityContent>
    </Activity>
  );
}

@layer components {
  :where([data-control-family="chat-layout"][data-slot="root"]) {
    --cui-chat-layout-radius: var(--radius-scene);
    --cui-chat-layout-background: var(--background);
    --cui-chat-layout-border-color: var(--border);
    --cui-chat-layout-shadow: var(--shadow-md);
    --cui-chat-layout-thought-foreground: var(--muted-foreground);
    --cui-chat-layout-thought-hover-background: oklch(from var(--foreground) l c h / 0.04);
    background: var(--cui-chat-layout-background);
    border: 1px solid var(--cui-chat-layout-border-color);
    border-radius: var(--cui-chat-layout-radius);
    box-shadow: var(--cui-chat-layout-shadow);
  }

  :where([data-control-family="chat-layout"][data-chat-layout-kind="thread"][data-slot="root"]) {
    gap: calc(var(--spacing) * 8);
    padding-block: calc(var(--spacing) * 6);
    padding-inline: calc(var(--spacing) * 4);
  }

  @media (width >= 40rem) {
    :where([data-control-family="chat-layout"][data-chat-layout-kind="thread"][data-slot="root"]) {
      padding-inline: calc(var(--spacing) * 8);
    }
  }

  :where([data-control-family="chat-layout"][data-chat-layout-kind="thought"][data-slot="root"]) {
    margin-block: 0 calc(var(--spacing) * 2);
  }

  :where([data-control-family="chat-layout"][data-slot="trigger"]) {
    min-block-size: 0;
    inline-size: fit-content;
    gap: calc(var(--spacing) * 1);
    padding-inline: calc(var(--spacing) * 1.5);
    padding-block: calc(var(--spacing) * 1);
    border-radius: var(--radius-control);
    color: var(--cui-chat-layout-thought-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }

  @media (hover: hover) {
    :where([data-control-family="chat-layout"][data-slot="trigger"]:hover) {
      background: var(--cui-chat-layout-thought-hover-background);
      color: var(--foreground);
    }
  }

  :where([data-control-family="chat-layout"][data-slot="chevron"]) {
    font-size: var(--text-sm);
    line-height: 1;
    transition: rotate var(--duration-base) var(--ease-emphasized);
  }

  :where([data-control-family="chat-layout"][data-slot="details"]) {
    padding-inline: calc(var(--spacing) * 1);
    padding-block: calc(var(--spacing) * 1) calc(var(--spacing) * 2);
    color: var(--muted-foreground);
    font-size: var(--text-caption);
    line-height: calc(var(--spacing) * 5);
  }

  :where([data-control-family="chat-layout"][data-slot="title"]) {
    color: var(--muted-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="chat-layout"][data-slot="trigger"][data-state="open"] > span:last-child) {
    rotate: 90deg;
  }
}

@property --cui-chat-layout-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-chat-layout-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-layout-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-layout-shadow {
  syntax: "*";
  inherits: true;
}

@property --cui-chat-layout-thought-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-chat-layout-thought-hover-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}
